import {html as coreHtml, mathml as coreMathml, svg as coreSvg} from "./html.js"

/**
 * Предотвращает атаки с внедрением JSON.
 *
 * Цели этой метки:
 *   1) быстрая проверка
 *   2) малый размер кода при передаче
 *   3) несколько версий @metafor/html на одной странице будут производить взаимно совместимые StaticValue
 *   4) обычный JSON.parse (без специального reviver) не может создать StaticValue
 *
 * Символы удовлетворяют (1), (2) и (4). Мы используем Symbol.for для (3),
 * но нам не важен ключ, поэтому для (2) используем пустую строку.
 */
export type Brand = symbol


export interface StaticValue {
  /** Значение для интерполяции как есть в шаблон */
  _$htmlStatic$: string

  /**
   * Значение, которое не может быть декодировано из обычного JSON,
   * что усложняет для атакующего возможность создать валидное StaticValue
   * через контролируемые данные, проходящие через JSON.parse
   */
  r: Brand
}

/**
 * Обёртка для тегов шаблонов `@metafor/html` (`html`, `svg` или `mathml`), добавляющая поддержку статических значений.
 *
 * @remarks
 * Позволяет использовать `unsafeStatic`-значения внутри шаблонных литералов, объединяя их с соседними строками для оптимизации.
 *
 * @param coreTag - Базовая функция-тег (`html`, `svg` или `mathml`), которую нужно обернуть.
 * @returns Функцию-тег, обрабатывающую как динамические, так и статические значения.
 *
 * @example
 * ```ts
 * const html = withStatic(coreHtml);
 * html`<div>${unsafeStatic('Статический текст')}</div>`;
 * ```
 */
declare function withStatic(
  coreTag: typeof coreHtml | typeof coreSvg | typeof coreMathml
): (
  strings: TemplateStringsArray,
  ...values: unknown[]
) => ReturnType<typeof coreHtml | typeof coreSvg | typeof coreMathml>

/**
 * Помечает строковый литерал так, чтобы он вел себя как часть статического
 * шаблона, а не как динамическое значение.
 *
 * @remarks
 * - В выражениях шаблона можно использовать только другие результаты, помеченные
 *   как `literal` или значения `unsafeStatic`.
 * - **Важно:** Недоверенный контент никогда не должен передаваться в `unsafeStatic`.
 * - Пользователи должны убедиться, что добавление статической строки приводит к
 *   корректному HTML, иначе шаблоны могут сломаться.
 * - Статические значения можно изменять, но это вызовет полный перерендер
 *   (так как фактически создаётся новый шаблон).
 *
 * @param strings - Шаблонные строки (Template Strings)
 * @param values - Значения для вставки (только `StaticValue` или `unsafeStatic`)
 * @returns Объект `StaticValue` для использования в шаблонах
 *
 * @example
 * ```ts
 * const staticPart = literal`<div class="header">`;
 * html`${staticPart}Динамический контент</div>`;
 * ```
 */
export declare function literal(
  strings: TemplateStringsArray,
  ...values: unknown[]
): StaticValue

/**
 * Оборачивает строку так, чтобы она вела себя как часть статического шаблона,
 * а не как динамическое значение.
 *
 * Пользователи должны убедиться, что добавление статической строки в шаблон
 * приводит к корректному HTML, иначе шаблоны могут неожиданно сломаться.
 *
 * Важно: эта функция небезопасна для недоверенного контента, так как он будет
 * напрямую парситься в HTML. Не передавайте пользовательский ввод в эту функцию
 * без предварительной санитизации.
 *
 * Статические значения можно изменять, но это вызовет полный перерендер,
 * так как фактически создается новый шаблон.
 */
export declare function unsafeStatic(value: string): StaticValue